const rows = $input.all().map(i => i.json);

const num = (v) => Number(v || 0);

// Find latest date in dataset
const allDates = rows.map(r => new Date(r.date));
const latestDate = new Date(Math.max(...allDates));

// Normalize date
latestDate.setHours(0,0,0,0);

const DAY = 1000 * 60 * 60 * 24;

// Difference from latest date
function dayDiff(dateStr) {
  const d = new Date(dateStr);
  d.setHours(0,0,0,0);
  return Math.floor((latestDate - d) / DAY);
}

// Current week = latest 7 days
const thisWeek = rows.filter(r => {
  const d = dayDiff(r.date);
  return d >= 0 && d < 7;
});

// Previous week
const lastWeek = rows.filter(r => {
  const d = dayDiff(r.date);
  return d >= 7 && d < 14;
});

const sumRevenue = arr => arr.reduce((a,r)=>a+num(r.revenue),0);
const sumUnits = arr => arr.reduce((a,r)=>a+num(r.units_sold),0);

const totalRevenueThisWeek = sumRevenue(thisWeek);
const totalRevenueLastWeek = sumRevenue(lastWeek);

const totalOrdersThisWeek = sumUnits(thisWeek);

const revenueChangePct =
totalRevenueLastWeek === 0
? 0
: Number((((totalRevenueThisWeek-totalRevenueLastWeek)/totalRevenueLastWeek)*100).toFixed(1));

const avgOrderValue =
totalOrdersThisWeek === 0
? 0
: Math.round(totalRevenueThisWeek/totalOrdersThisWeek);

// Aggregate products
function aggregate(arr){
  const obj = {};
  for(const r of arr){
    const p = r.product_name;
    if(!obj[p]){
      obj[p]={
        revenue:0,
        units:0
      };
    }
    obj[p].revenue += num(r.revenue);
    obj[p].units += num(r.units_sold);
  }
  return obj;
}

const thisAgg = aggregate(thisWeek);
const lastAgg = aggregate(lastWeek);

// Top products
const top3Products =
Object.entries(thisAgg)
.sort((a,b)=>b[1].revenue-a[1].revenue)
.slice(0,3)
.map(([name,data])=>({
product_name:name,
revenue:data.revenue,
units_sold:data.units,
change_vs_last_week_pct:
lastAgg[name]
? Number((((data.revenue-lastAgg[name].revenue)/lastAgg[name].revenue)*100).toFixed(1))
: null
}));

// Declining product
let decliningProduct = null;
let biggestDrop = 0;

for(const p in lastAgg){

if(!thisAgg[p]) continue;

const prev = lastAgg[p].revenue;
const curr = thisAgg[p].revenue;

if(prev===0) continue;

const drop=((prev-curr)/prev)*100;

if(drop>biggestDrop){
biggestDrop=drop;
decliningProduct=p;
}

}

const months=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];

const reportDate=`${latestDate.getDate()} ${months[latestDate.getMonth()]} ${latestDate.getFullYear()}`;

return [
{
json:{
report_date:reportDate,

total_revenue_this_week:totalRevenueThisWeek,

total_revenue_last_week:totalRevenueLastWeek,

revenue_change_pct:revenueChangePct,

total_orders_this_week:totalOrdersThisWeek,

avg_order_value:avgOrderValue,

top_3_products:top3Products,

declining_product:decliningProduct,

declining_product_drop_pct:Number(biggestDrop.toFixed(1))
}
}
];

