const metrics = $('Calculate Metrics').first().json;
const fallback = {
  executive_summary: 'Weekly sales report generated successfully. Review the metrics below for performance details.',
  top_insight: 'Top product maintained strong revenue performance this week.',
  warning: 'Monitor the declining product closely — continued drop may require pricing or inventory action.',
  recommended_action: "Review ad spend allocation for underperforming products before next week's campaign.",
  week_sentiment: 'neutral',
};
let parsed = null;
try {
  const item = $input.first().json || {};
  let raw = '';
  if (Array.isArray(item.output) && item.output[0] && Array.isArray(item.output[0].content) && item.output[0].content[0]) {
    raw = item.output[0].content[0].text;
  } else if (typeof item.text === 'string') {
    raw = item.text;
  } else if (item.message && item.message.content != null) {
    raw = item.message.content;
  } else if (item.content != null) {
    raw = item.content;
  }
  if (raw && typeof raw === 'object') {
    parsed = raw;
  } else if (typeof raw === 'string' && raw.trim()) {
    const BT = String.fromCharCode(96);
    let s = raw.split(BT).join('').trim();
    if (s.toLowerCase().indexOf('json') === 0) s = s.slice(4).trim();
    const start = s.indexOf('{');
    const end = s.lastIndexOf('}');
    if (start !== -1 && end !== -1) s = s.slice(start, end + 1);
    parsed = JSON.parse(s);
  }
} catch (e) {
  parsed = null;
}
const ai = parsed && typeof parsed === 'object' ? parsed : fallback;
const aiClean = {};
for (const k of Object.keys(fallback)) {
  aiClean[k] = (ai[k] == null || ai[k] === '') ? fallback[k] : ai[k];
}
return [{ json: Object.assign({}, metrics, aiClean) }];
